'use strict';

/**
* LAPACK routine to compute a LQ factorization of a real M-by-N matrix `A`.
*
* @module @stdlib/lapack/base/dgelqf
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dgelqf = require( '@stdlib/lapack/base/dgelqf' );
*
* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
* var TAU = new Float64Array( 3 );
* var WORK = new Float64Array( 4 );
*
* dgelqf( 'column-major', 3, 4, A, 3, TAU, WORK, 4 );
* // A => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0.0, ~0.618, ~-0.789, ~0.618 ]
* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
* // WORK => <Float64Array>[ 3.0, ~24.593, 0.0, 0.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dgelqf;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dgelqf = main;
} else {
	dgelqf = tmp;
}


// EXPORTS //

module.exports = dgelqf;

// exports: { "ndarray": "dgelqf.ndarray" }
